"""議論與應用類文章（100 篇）。

訓練重點：分辨「論點」與「論據」，聽懂對方為什麼反對，並認識應用文的格式。
這一類的文章有兩個方向：一是議論文，作者要針對一個問題說明立場並提出理由；
二是應用文，格式本身就是內容的一部分（書信有稱謂與祝語，啟事有遺失資訊，
說明書有步驟與警告）。讀應用文時，看漏一行格式，重點就可能整段錯過。
"""

